// Keyboard steps of the logit-lens slide (figure generated by tools/lens_slide.py).
//
// Adds data-steps fragments to every <div class="lp" data-steps="N"> (themes/steps.js), so
// the arrow keys step through it, one group of layers per key, and posts the step to the
// script inside its <object> SVG, which shows the groups.
// In the PDF nothing is posted: the SVG shows its final state.
(() => {
  document.querySelectorAll('div.lp[data-steps]:not(.lp-built)').forEach((root) => {
    root.classList.add('lp-built');
    const obj = root.querySelector('object');
    // a new URL on every page load: browsers (Firefox) keep an <object> in their cache even on a forced reload
    obj.data = obj.getAttribute('data').replace(/\?.*$/, '') + '?t=' + Date.now();

    // the SVG's window: Firefox gives a file:// page no obj.contentWindow, so it is
    // also taken from the source of the SVG's ready message
    let st = null, svgWin = null;
    function post() {
      const win = obj.contentWindow || svgWin;
      if (st !== null && win) win.postMessage({ lens: st }, '*');
    }
    steps(root, +root.dataset.steps, (s) => { st = s; post(); });
    // the SVG loads after this runs: send it the current step once it is ready
    window.addEventListener('message', (ev) => {
      if (!ev.data || !ev.data.lensReady || (obj.contentWindow && ev.source !== obj.contentWindow)) return;
      svgWin = ev.source;
      post();
    });
    obj.addEventListener('load', post);
  });
})();
